/* The cursor on the landing page: a black fingerless leather glove with
   studded knuckles and a spiked cuff, painted in the manner of Streets of
   Rage 4, pointing top-left (glove E, his Midjourney pick, 7 Oct 2026).
   Every now and then (EVERY ms, give or take) it stretches its fingers out,
   holds the stretch, and goes back to pointing: straight cuts (IN/OUT ms a frame),
   and the hand eases out a touch while open. A tremble on the hold ("cheesy")
   and cross-fades between frames ("weird blurry overlay") were both tried (9 Oct;
   a clenched fist was tried first and he preferred the stretch). The gesture
   frames are Copilot edits of the same picture, lined up on the cuff by
   designs/glove-mj/align_fist.py so only the hand moves; FRAMES lists them
   in playing order, any in-betweens first, the full stretch last.
   The first stretch comes FIRST ms after the glove appears, once per page. Clicking presses it in a touch. Nothing tells anyone it does this.
   Moved fast, the hand swings on the fingertip: the cuff trails behind the way it's going and settles
   when it stops (a damped spring on .w, so the frames and the press are untouched). Kept gentle: the
   first cut (9 deg per px/ms, up to 22) was "a bit too intense", and so was the second (4, up to 10), 9 Oct. A claw over every link was
   tried the same day and ditched ("too much").
   A knuckle crack (stretch, fold the fingers down, a pop) was tried too and ditched: "it looks like a
   boob grab" (9 Oct). The fold frame is glove_K_aligned_pad.png, unused.
   Smoke on idle (a wisp, then a trail behind the hand) is parked in designs/glove-mj/glove.template.smoke-parked.js:
   no cigarette yet, and he wasn't sure a cigarette is a good look for employers (9 Oct).
   Fine pointer only (phones have no cursor). ?glove=0 off, ?every=<ms> to
   see the stretch more often. Over the game's iframe the glove hides and
   the game's own cursor takes over. */
(function(){
  var q=location.search;
  if(/[?&]glove=0/.test(q)) return;
  if(!matchMedia('(hover:hover) and (pointer:fine)').matches) return;
  var m=q.match(/[?&]every=(\d+)/), EVERY=m?+m[1]:20000;   /* every now and then: ~20s, give or take 30% (his ask, 9 Oct) */
  var IN=[60,60,60,55,100], OUT=45, HOLD=500, FIRST=2500;
  /* a stretch, not a reveal (9 Oct: "it just looks like it's showing its fingers"): it opens slower
     frame by frame, the wrist tips back as it reaches the full stretch and pushes there through the
     hold, then lets go fast. ms per frame going in; per frame going out; the hold; the first one. */
  var POINT='data:image/webp;base64,', FRAMES=["data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,", "data:image/webp;base64,"];
  var W=82.5, H=89.0, HX=14.0, HY=13.5;   /* hotspot: the fingertip */
  var still=matchMedia('(prefers-reduced-motion:reduce)').matches;
  var css=document.createElement('style');
  css.textContent=
    'html.glove-on,html.glove-on *{cursor:none!important}'+
    '#glove{position:fixed;left:0;top:0;width:'+W+'px;height:'+H+'px;pointer-events:none;'+
      'z-index:2147483000;opacity:0;will-change:transform}'+
    '#glove.on{opacity:1}'+
    '#glove .w{transform-origin:'+(HX/W*100)+'% '+(HY/H*100)+'%}'+
    '#glove .g{position:relative;transform-origin:72% 88%;transition:transform .22s cubic-bezier(.4,0,.6,1)}'+
    '#glove img{display:block;width:100%;height:auto}'+
    '#glove img+img{position:absolute;left:0;top:0;opacity:0}'+
    '#glove.open .g{transform:rotate(6deg) scale(1.04);transition:transform .6s cubic-bezier(.2,.6,.3,1)}'+
    /* ⛔ 16 Oct, his note: "I don't like how far the cursor goes down when you click". The press shrank the hand toward
       its cuff, which dragged the fingertip down and right. Now it presses in place ON the fingertip (the .w wrapper's
       origin), lighter, via the separate 'scale' property so it never fights the swing's transform. */
    '#glove .w{transition:scale .14s cubic-bezier(.3,.7,.4,1)}'+
    '#glove.down .w{scale:.94;transition-duration:.06s}';
  document.head.appendChild(css);
  var el=document.createElement('div'), w=document.createElement('div'), g=document.createElement('div');
  el.id='glove'; el.setAttribute('aria-hidden','true'); w.className='w'; g.className='g';
  var imgs=[POINT].concat(FRAMES).map(function(src){
    var im=new Image(); im.alt=''; im.src=src; g.appendChild(im); return im;
  });
  /* 18 Oct: the hold pose (his 4th Copilot run: fingers curling away, grabbing) — shown only while lure.js has hold of the note */
  var GRIP='data:image/webp;base64,', gripIm=null;
  if(GRIP){ gripIm=new Image(); gripIm.alt=''; gripIm.src=GRIP; gripIm.style.opacity=0; g.appendChild(gripIm); }
  w.appendChild(g); el.appendChild(w); document.body.appendChild(el);
  var cur=0, auto=0, steps=[], shown=false;
  function op(im,v){ im.style.opacity=v; }
  function to(i){ op(imgs[i],1); op(imgs[cur],0); cur=i; }
  function stop(){
    steps.forEach(clearTimeout); steps=[]; el.classList.remove('open');
    imgs.forEach(function(im,i){ op(im,i?0:1); }); cur=0;
  }
  function stretch(){
    var n=imgs.length-1, t=0; if(!n||still) return; stop();
    for(var i=1;i<=n;i++){ steps.push(setTimeout(to.bind(null,i),t)); t+=IN[Math.min(i-1,IN.length-1)]; }
    steps.push(setTimeout(function(){ el.classList.add('open'); },t-IN[IN.length-1]));   /* the wrist tips back as the last frame lands */
    t+=HOLD; steps.push(setTimeout(function(){ el.classList.remove('open'); },t));
    for(i=n-1;i>=0;i--){ steps.push(setTimeout(to.bind(null,i),t)); t+=OUT; }
  }
  function every(){
    clearTimeout(auto);
    auto=setTimeout(function(){ if(el.classList.contains('on')&&!held) stretch(); every(); },
      EVERY*(.7+Math.random()*.6));
  }
  /* the swing: how fast the pointer is going sets where the hand wants to hang (the cuff sits below
     and right of the fingertip, so going right or up swings it clockwise); a spring chases that */
  var vx=0, vy=0, lx=0, ly=0, lt=0, ang=0, spin=0, raf=0;
  var SWING=2, MAXDEG=5;   /* degrees per px/ms of speed; the most it ever swings */
  function swing(){
    var aim=Math.max(-MAXDEG,Math.min(MAXDEG,SWING*(vx-vy)));
    spin=(spin+(aim-ang)*.14)*.76; ang+=spin;
    vx*=.85; vy*=.85;   /* speed bleeds away when the pointer stops */
    w.style.transform='rotate('+ang.toFixed(2)+'deg)';
    raf=(Math.abs(ang)+Math.abs(spin)+Math.abs(vx)+Math.abs(vy)>.01)?requestAnimationFrame(swing):0;
    if(!raf) w.style.transform='';
  }
  function speed(e){
    var t=e.timeStamp, dt=t-lt;
    if(lt&&dt>0&&dt<100){ vx=vx*.6+(e.clientX-lx)/dt*.4; vy=vy*.6+(e.clientY-ly)/dt*.4; }
    lx=e.clientX; ly=e.clientY; lt=t;
    if(!still&&!raf) raf=requestAnimationFrame(swing);
  }
  function move(e){
    speed(e);
    el.style.transform='translate3d('+(e.clientX-HX)+'px,'+(e.clientY-HY)+'px,0)';
    if(!el.classList.contains('on')){
      el.classList.add('on'); document.documentElement.classList.add('glove-on');
      /* the first one comes early, once per page, so people see it does this */
      if(!shown){ shown=true; clearTimeout(auto); auto=setTimeout(function(){ if(el.classList.contains('on')) stretch(); every(); },FIRST); }
      else every();
    }
  }
  /* ⛳ 18 Oct, his ask: "we had a grab cursor state didn't we? use that when you grab onto the note". While lure.js has hold of the
     $100 the hand closes to the claw frame and holds it (the claw over every link was "too much"; this is only while holding). */
  var held=false;
  window.mmGloveGrip=function(on){
    /* ⛔ 5:37pm "the claw doesn't feel like a grab", and Copilot's fist was "bad": holding is the pointing hand, pressed in */
    if(on){ held=true; stop(); clearTimeout(auto); if(gripIm){ op(imgs[cur],0); op(gripIm,1); } else el.classList.add('down'); }
    else if(held){ held=false; if(gripIm){ op(gripIm,0); op(imgs[0],1); cur=0; } el.classList.remove('down'); every(); }
  };
  addEventListener('pointermove',function(e){ if(e.pointerType==='mouse') move(e); },{passive:true});
  addEventListener('pointerdown',function(e){ if(e.pointerType==='mouse'){ stop(); el.classList.add('down'); } });
  addEventListener('pointerup',function(){ el.classList.remove('down'); });
  /* leaving the window, or going over the game iframe: put the glove away */
  document.addEventListener('pointerout',function(e){
    var t=e.relatedTarget;
    if(!t||t.tagName==='IFRAME'){ el.classList.remove('on'); clearTimeout(auto); stop(); }
  });
})();
